custom_css:
/* ST 原版主题。 */
/* 字体：下载地址和字体名称。 */
@import url("https://fontsapi.zeoseven.com/415/main/result.css");

:root { --softlight-theme-id: silver-mist-b; --mainFontFamily: "WenYuan Serif SC VF", "WenYuan Serif SC", "Songti SC", "SimSun", serif !important; }
body { font-family: var(--mainFontFamily); font-weight: normal; }
:is(input,textarea,select,button,.text_pole,.text_input,.menu_button):not([class*="fa-"]):not(.fa):not(.fas):not(.far):not(.fab):not(.monospace) {
  font-family: var(--mainFontFamily);
}

/* 正文字重和行距：450 是粗细，1.72 是行高，.012em 是字间距。 */
#chat > .mes:not(.smallSysMes) .mes_text {
  font-weight:450 !important; line-height:1.72 !important;
}
#chat > .mes:not(.smallSysMes) .mes_text > p {
  font-weight:450 !important; line-height:1.72 !important; letter-spacing:.012em !important;
  text-align:justify; text-align-last:left;
}
#chat > .mes:not(.smallSysMes) .mes_text :is(strong,b) {font-weight:600 !important;}


/* 背景：dim 调暗度，blur 调模糊，x/y 调位置，font 调字号；使用插件时在插件里调背景。 */
:root {
  --scene-image: none; 
  --scene-dim: .60;
  --scene-blur: 0px;
  --scene-x: 50%;
  --scene-y: 25%;
  --scene-font: 17px;
  --scene-ink: var(--SmartThemeBodyColor, #e3e3e3);
  --scene-muted: #a7a7a7;
/* 玻璃：mist 调底色，edge 调边线；rgba 最后一项越小越淡。drawer-blur 调面板模糊，radius 调圆角。 */
  --scene-mist: rgba(255,255,255,.055);
  --scene-edge: rgba(255,255,255,.09);
  --scene-drawer-tint:rgb(31,31,31);
  --scene-drawer-blur:0px;
  --scene-radius: 26px;
}


/* 背景图和黑色遮罩。 */
body { background-color: #171717; text-shadow: none; }
/* 透明背景的底色也参与亮度调节。 */
html #bg1 { background-color: #171717; }
#bg1, #bg_custom {
  background-position: var(--scene-x) var(--scene-y) !important;
  filter: blur(var(--scene-blur));
}
body::before {
  content: ""; position: fixed; inset: 0; z-index: 1; pointer-events: none;
  background: var(--scene-image) var(--scene-x) var(--scene-y) / cover no-repeat;
  filter: blur(var(--scene-blur));
}
body::after {
  content: ""; position: fixed; inset: 0; z-index: 2; pointer-events: none;
  background: rgba(0,0,0,var(--scene-dim));
}
/* 聊天区域的宽度、留白和消息排版。 */
#sheld { background: transparent !important; border: 0; box-shadow: none; }
#chat {
  background: transparent !important; border: 0 !important; box-shadow: none;
  backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
  min-height: 0; max-height: none; flex: 1 1 0;
  padding: 26px 24px 24px; gap: 30px; text-shadow: none;
  scrollbar-width: thin; scrollbar-color: #ffffff26 transparent;
}
#chat > .mes:not(.smallSysMes) {
  display: block; position: relative; width: 100%; flex: 0 0 auto;
  padding: 0 0 22px; margin: 0; color: var(--scene-ink);
  background: transparent !important; border: 0 !important;
  border-radius: 0; box-shadow: none !important;
}
#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper { display: none; }
#chat > .mes:not(.smallSysMes) > .mes_block { width: 100%; padding: 0; overflow: visible; }
#chat > .mes:not(.smallSysMes) .ch_name {
  gap: 7px; flex-wrap: wrap; align-items: center; min-height: 32px; margin-bottom: 14px;
}
#chat > .mes:not(.smallSysMes) .name_text {
  color: var(--scene-muted); font-size: .82em; font-weight: 400;
  letter-spacing: .045em; overflow-wrap: anywhere;
}
#chat > .mes[is_user="false"]:not(.smallSysMes) .name_text::before {
  content: ""; display: inline-block; width: 4px; height: 4px;
  border-radius: 50%; margin: 0 10px 3px 2px; background: #ddd;
  box-shadow: 0 0 7px 2px #ffffff2b; pointer-events: none;
}
#chat > .mes:not(.smallSysMes) .timestamp { font-size: .7em; color: var(--scene-muted); }
#chat > .mes:not(.smallSysMes) :is(.mes_buttons,.mes_edit_buttons) {
  color: var(--scene-muted); opacity: .8; flex-wrap: wrap;
}
#chat > .mes:not(.smallSysMes) :is(.mes_text,.mes_reasoning) {
  font-family: var(--mainFontFamily,"Noto Sans"),"PingFang SC","Microsoft YaHei",sans-serif;
  font-size: calc(var(--scene-font) * var(--fontScale,1)) !important;
  line-height: 1.9; font-weight: 400; color: var(--scene-ink);
  padding: 0; overflow-wrap: anywhere; text-shadow: none;
}
#chat > .mes:not(.smallSysMes) .mes_text p { margin: 0 0 1.15em; }
#chat > .mes:not(.smallSysMes) .mes_text p:last-child { margin-bottom: 0; }

/* 用户消息：头像靠右，调整文字框和名字的位置。 */
#chat > .mes[is_user="true"]:not(.smallSysMes) {
  display: grid; grid-template-columns: minmax(0,680px) 40px;
  justify-content: end; align-items: start;
  column-gap: 12px; row-gap: 0; padding-left: 24px;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper {
  display: block; grid-column: 2; grid-row: 3; align-self: start; margin: 0;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper .avatar {
  width: 40px; height: 40px; margin: 0; border-radius: 50%;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
  width: 100%; height: 100%; object-fit: cover; border-radius: inherit;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block {
  display: contents;
}

#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > * {
  grid-column: 1; min-width: 0;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .ch_name { grid-row: 1; }
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .mes_reasoning_details { grid-row: 2; }
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .mes_text {
  grid-row: 3; align-self: start;
}

#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .ch_name,
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .ch_name > .flex1,
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .ch_name > .flex1 > .flex-container {
  display: contents;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) .name_text {
  grid-column: 2; grid-row: 3; align-self: start; justify-self: center; margin: 46px 0 0; text-align: center;
  line-height: 1.4; white-space: normal; overflow-wrap: anywhere;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) :is(.mes_buttons,.mes_edit_buttons) {
  grid-column: 1; grid-row: 1; justify-self: start;
  min-height: 24px; margin-bottom: 8px;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) :is(.timestamp,.mes_ghost) {
  grid-column: 1; grid-row: 1; align-self: center; justify-self: end;
}

#chat > .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper .avatar {
  margin-bottom: calc(2.4em + 6px);
}
#chat > .mes[is_user="true"]:not(.smallSysMes) .mes_text {
  box-sizing: border-box; width: fit-content; max-width: 100%;
  margin: 12px 0 0 auto; padding: 9px 11px; text-align: left; line-height: 1.45;

  color: var(--scene-ink); background: rgba(45,45,45,.40);
  border: 1px solid rgba(255,255,255,.10); border-radius: 14px;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  box-shadow: 0 6px 14px rgba(0,0,0,.12), inset 0 1px 0 rgba(255,255,255,.05);
  text-shadow: none;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) .mes_text:empty {
  padding: 0; border: 0; background: none; box-shadow: none;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
#chat > .mes[is_user="true"]:not(.smallSysMes) .mes_text p { margin-bottom: .65em; }
#chat > .mes[is_user="true"]:not(.smallSysMes) .mes_text p:last-child { margin-bottom: 0; }

/* 斜体、引用、下划线和链接颜色。 */
#chat .mes_text :is(em,i) { color: var(--SmartThemeEmColor, #bdbdbd); }
#chat .mes_text q :is(em,i) { color: inherit; }
#chat .mes_text q { color: var(--SmartThemeQuoteColor, #f2f2f2); background: none; }
#chat .mes_text u { color: var(--SmartThemeUnderlineColor, #d1d1d1); text-decoration-color: currentColor; text-underline-offset: 4px; }
#chat .mes_text a { color: #ddd; text-underline-offset: 4px; }
#chat .mes_text blockquote {
  margin: 14px 0; padding: 0 15px; border-left: 1px solid var(--SmartThemeQuoteColor, #f2f2f2); color: inherit;
}
#chat .mes_text pre { max-width: 100%; overflow: auto; background: #1c1c1ce6; border-radius: 12px; }
#chat .mes_text img { max-width: 100%; height: auto; }
/* 思考过程的装饰图片。 */
:root { --silver-thread-art: url("https://i.postimg.cc/pV5MFvYZ/si-kao-guo-cheng-yin-si-zhuang-shi.png"); }

/* 思考过程：折叠按钮、标题和展开后的文字。 */
#chat .mes_reasoning_details {
  background: transparent; border: 0; border-radius: 0;
  padding: 0; margin: 0 0 14px; box-shadow: none;
}
#chat .mes_reasoning_details .mes_reasoning_summary {
  list-style: none; margin: 0; padding: 0;
  align-items: center; flex-wrap: wrap; gap: 4px 12px;
}
#chat .mes_reasoning_summary::-webkit-details-marker { display: none; }
#chat .mes_reasoning_header_block { flex: 1 1 auto; min-width: 150px; }
#chat .mes_reasoning_header {
  position: relative; box-sizing: border-box;
  margin: 0; padding: 0; border: 0; border-radius: 10px;
  background: transparent; box-shadow: none; align-items: center;
}
#chat .mes_reasoning_header::before {
  content: ""; position: absolute; left: 0; top: 4px; pointer-events: none;
  background: var(--silver-thread-art) center / contain no-repeat;
  opacity: .82; transition: opacity .18s ease;
}

#chat .mes_reasoning_header_title {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}
#chat .mes_reasoning_details .mes_reasoning_arrow {
  display: none;
}
#chat .mes_reasoning_summary:hover .mes_reasoning_header::before,
#chat .mes_reasoning_summary:focus-visible .mes_reasoning_header::before { opacity: 1; }
#chat .mes_reasoning_summary:focus-visible {
  outline: 1px solid #ffffff55; outline-offset: 3px; border-radius: 8px;
}
#chat > .mes:not(.smallSysMes) .mes_reasoning_details .mes_reasoning {
  position: relative; margin: 0 0 8px 6px; padding: 8px 14px 10px 19px;
  border-left: 1px solid #ffffff30; border-radius: 15px 0 0 0;
  background: transparent; color: #bcbcbc; line-height: 1.8;
  font-size: calc(var(--scene-font) * var(--fontScale,1) * .85) !important;
  overflow-wrap: anywhere;
}

#chat .mes_reasoning_details .mes_reasoning :is(h1,h2,h3,h4,h5,h6,p,li,blockquote,pre,code,table) {
  font-size: 1em !important;
}
#chat .mes_reasoning_details .mes_reasoning :is(h1,h2,h3,h4,h5,h6) {
  font-weight: 600; line-height: 1.6; margin-block: 1em .5em;
}
#chat .mes_reasoning_details[open] .mes_reasoning:not(:empty)::before {
  content: ""; position: absolute; left: -3px; top: 18px;
  width: 5px; height: 5px; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle at 30% 25%,#fff,#c9c9c9 55%,#777);
  box-shadow: 0 0 5px #ffffff24;
}
#chat .mes_reasoning_actions {
  margin: 0; gap: 8px; flex-wrap: wrap; align-items: center; color: #bcbcbc;
}
#chat .mes_reasoning_actions .mes_button { opacity: .75; }
#chat .mes_reasoning_actions .mes_button:hover { opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  #chat .mes_reasoning_header::before { transition: none; }
}

#chat .edit_textarea {
  color: var(--scene-ink);
  background: #202020ed;
  min-height: 160px;
  font-size: calc(var(--scene-font) * var(--fontScale, 1)) !important;
}
#chat > .mes.selected:not(.smallSysMes) { outline: 1px solid #ffffff66 !important; background: #ffffff09 !important; }
#chat > .mes:not(.smallSysMes) :is(.swipe_left,.swipeRightBlock) { bottom: 0; color: #bdbdbd; z-index: 3; }


/* 底部输入栏：位置、玻璃底色和圆角。 */
#form_sheld {
  flex-shrink: 0; margin: 0; padding: 8px 12px max(8px,env(safe-area-inset-bottom));
  background: transparent !important;
}
#send_form, body.no-blur #send_form {
  display: flex; flex-direction: row !important; flex-wrap: wrap !important;
  align-items: center; width: 100%; padding: 5px;
  background: var(--scene-mist) !important;
  border: 1px solid var(--scene-edge) !important;
  border-radius: var(--scene-radius) !important;
  backdrop-filter: blur(16px) !important; -webkit-backdrop-filter: blur(16px) !important;
  box-shadow: 0 6px 22px #00000016 !important;
  transition: border-color .2s ease, box-shadow .2s ease;
}
#send_form:focus-within {
  border-color: #ffffff29 !important;
  box-shadow: 0 0 16px #ffffff05, 0 6px 22px #00000016 !important;
}
#send_form #nonQRFormItems {
  display: flex; flex-direction: row; flex-wrap: nowrap;
  align-items: center; width: 100%; min-width: 0; flex: 0 0 100%;
}
#send_form #send_textarea {
  font-size: 16px; line-height: 1.5; border: 0; padding: 10px 8px;
  min-height: 44px; min-width: 0; resize: none;
  background: transparent !important; box-shadow: none !important;
  color: var(--scene-ink) !important;
}

#send_form :is(#options_button,#send_but,#mes_stop) { color: #cfcfcf; filter: none; }


/* 输入辅助工具条：排在输入框上方，调整按钮大小和显示时机。 */
#send_form #qr--bar:has(#input_helper_toolbar) {
  order: 0 !important; flex: 0 0 100% !important;
  width: 100% !important; min-width: 0 !important; max-width: 100%;
  flex-wrap: wrap !important; box-sizing: border-box;
}
#send_form #qr--bar:has(#input_helper_toolbar):not(:has(> :not(#input_helper_toolbar))) {
  margin-block: 0 !important; padding-block: 0 !important; row-gap: 0 !important;
}
#send_form #input_helper_toolbar {
  order: 0 !important; flex: 0 0 100% !important;
  width: 100% !important; min-width: 0 !important; max-width: 100%;
  height: auto !important; min-height: 0 !important; max-height: 28px !important;
  box-sizing: border-box; flex-flow: row nowrap !important;
  align-items: center; justify-content: center !important;
  justify-content: safe center !important;
  gap: 4px; margin: 0 !important; padding: 2px 6px !important;
  overflow-x: auto !important; overflow-y: hidden !important; scrollbar-width: thin;
  background: transparent; border: 0; box-shadow: none;
}

#send_form #input_helper_toolbar:not([hidden]):not(.hidden):not([style*="display: none" i]):not([style*="display:none" i]) {
  display: flex !important;
}
#send_form #nonQRFormItems:has(#input_helper_toolbar) { flex-wrap: wrap !important; }
#send_form #nonQRFormItems #input_helper_toolbar { order: -1 !important; }
#send_form #input_helper_toolbar :is(button,.input-helper-btn) {
  flex: 0 0 auto !important; width: auto !important;
  min-width: 28px !important; height: 24px !important; min-height: 0 !important;
  max-height: 24px !important; box-sizing: border-box;
  padding: 0 6px !important; margin: 0 !important; white-space: nowrap;
  font-size: 12px !important; line-height: 1 !important;
  align-items: center; justify-content: center;
  border-radius: 8px; border: 1px solid #ffffff0b;
  background: #ffffff04; box-shadow: none; color: #bdbdbd;
}

body:not(:has(#send_textarea:focus)):not(:has(#input_helper_toolbar:focus-within)):not(:has(#input_helper_toolbar:active)) #send_form #input_helper_toolbar {
  display: none !important;
}


/* 酒馆设置面板：底色、输入框和按钮。 */
.drawer-content, body.no-blur .drawer-content {
  background: var(--scene-drawer-tint) !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  border: 1px solid var(--scene-edge) !important;
  border-radius: 18px !important;
  box-shadow: 0 12px 36px #00000026 !important;
}

/* 弹窗与菜单使用不透明面板底色，遮住背后的聊天文字。 */
dialog.popup,#dialogue_popup,.select2-dropdown,.extensions_info,.TH-popup .popup[role="dialog"],#options,#extensionsMenu,.popup .popper-modal {background:var(--scene-drawer-tint) !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
.drawer-content :is(.inline-drawer-header,.standoutHeader,h4.title_restorable),
#user-settings-block h4 {
  background: transparent !important; border: 0 !important;
  border-bottom: 1px solid #ffffff09 !important; border-radius: 0 !important;
  box-shadow: none !important; text-shadow: none !important; filter: none !important;
  color: #dedede !important; font-weight: 500 !important;
  padding: 12px 8px !important; margin-block: 6px !important;
  min-height: 42px; box-sizing: border-box;
  transition: background-color .2s ease;
}
.drawer-content :is(.inline-drawer-header,.standoutHeader,h4.title_restorable) :is(b,strong,h3,h4),
#user-settings-block h4 :is(span,b,strong) { font-weight: inherit !important; text-shadow: none !important; }
#user-settings-block h4::before, #user-settings-block h4::after { content: none !important; }
.drawer-content .inline-drawer-content {
  background: transparent !important; border: 0 !important;
  box-shadow: none !important; border-radius: 0; padding: 8px 6px 14px;
}
.drawer-content :is(.text_pole,select,textarea,input[type="number"],input[type="text"],input[type="search"]) {
  background: #ffffff04 !important; border: 1px solid #ffffff0f !important;
  border-radius: 11px !important; box-shadow: none !important;
  color: var(--scene-ink);
}
.drawer-content select option { background: #262626; color: #e3e3e3; }
.drawer-content .menu_button {
  background: #ffffff06; border: 1px solid #ffffff12; border-radius: 10px; box-shadow: none;
}
.drawer-content .inline-drawer-header :is(.fa-circle-chevron-down,.fa-circle-chevron-up) {
  color: #bbbbbb !important; font-size: 14px !important; background: transparent !important;
  box-shadow: none !important; text-shadow: none !important; flex-shrink: 0; margin-left: 8px;
}
.drawer-content .inline-drawer-header .fa-circle-chevron-down::before { content: "\f107" !important; }
.drawer-content .inline-drawer-header .fa-circle-chevron-up::before { content: "\f106" !important; }
.drawer-content :is(input,textarea,select,.menu_button,.inline-drawer-header):focus-visible {
  outline: 1px solid #ffffff80; outline-offset: 2px;
}
.drawer-content :is(input,textarea,select):disabled { opacity: .45; }


/* 顶栏和底栏图标图片；b-icon-box 调大小。 */
:root { --b-icon-atlas: url("https://img2.tofaka.com/autoupload/f/5fapj/20260921/HKpg/1619X971/exec-9c86a4e3-c1d8-4ad3-993c-c4138b086583.png"); --b-icon-box: clamp(36px, calc(var(--mainFontSize,15px) * 2.7), 44px); }
#top-bar, body.no-blur #top-bar {
  background: transparent !important; border: 0 !important; box-shadow: none !important;
  backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
}
#top-settings-holder {
  border: 1px solid var(--scene-edge) !important;
  border-radius: 15px !important; box-shadow: none !important;
}
#top-settings-holder::before, #top-settings-holder::after { content: none !important; }
#top-settings-holder .drawer-icon { opacity: .95; text-shadow: none; }
#top-settings-holder #leftNavDrawerIcon,
#top-settings-holder #sys-settings-button .drawer-icon,
#top-settings-holder #advanced-formatting-button .drawer-icon,
#top-settings-holder #WIDrawerIcon,
#top-settings-holder #user-settings-button .drawer-icon,
#top-settings-holder #backgrounds-button .drawer-icon,
#top-settings-holder #extensions-settings-button .drawer-icon,
#top-settings-holder #persona-management-button .drawer-icon,
#top-settings-holder #rightNavDrawerIcon,
#send_form #options_button,
#send_form #extensionsMenuButton,
#rightSendForm :is(.fa-headphones,.fa-headphones-simple,.fa-headphones-alt), #rightSendForm #tts_media_control.fa-circle-play,
#send_form #send_but,
#send_form #mes_stop, #rightSendForm #tts_media_control:is(.fa-stop-circle,.fa-circle-stop) {
  position: relative; text-shadow: none !important;
}
#top-settings-holder #leftNavDrawerIcon::before,
#top-settings-holder #sys-settings-button .drawer-icon::before,
#top-settings-holder #advanced-formatting-button .drawer-icon::before,
#top-settings-holder #WIDrawerIcon::before,
#top-settings-holder #user-settings-button .drawer-icon::before,
#top-settings-holder #backgrounds-button .drawer-icon::before,
#top-settings-holder #extensions-settings-button .drawer-icon::before,
#top-settings-holder #persona-management-button .drawer-icon::before,
#top-settings-holder #rightNavDrawerIcon::before,
#send_form #options_button::before,
#send_form #extensionsMenuButton::before,
#rightSendForm :is(.fa-headphones,.fa-headphones-simple,.fa-headphones-alt)::before,
#rightSendForm #tts_media_control.fa-circle-play::before,
#send_form #send_but::before,
#send_form #mes_stop::before,
#rightSendForm #tts_media_control:is(.fa-stop-circle,.fa-circle-stop)::before {
  content: "" !important; display: block; position: absolute;
  left: calc(50% + var(--b-icon-box) * var(--b-shift-x));
  top: calc(50% + var(--b-icon-box) * var(--b-shift-y)); transform: translate(-50%,-50%);
  width: calc(var(--b-icon-box) * var(--b-crop-w)); height: calc(var(--b-icon-box) * var(--b-crop-h));
  background-image: var(--b-icon-atlas) !important;
  background-size: var(--b-crop-size) !important;
