/* 手机窄屏：聊天留白、输入栏高度和按钮间距。 */
@media (max-width: 600px) {
  #chat { padding: 20px 18px 20px; gap: 24px; }
  #chat > .mes[is_user="true"]:not(.smallSysMes) { padding-left: 16px; }
  #form_sheld { padding: 4px 8px max(4px,env(safe-area-inset-bottom)) !important; }
  body.PWA #form_sheld { padding-bottom: 4px !important; }
  #send_form, body.no-blur #send_form { padding: 3px 4px !important; }
  #send_form #nonQRFormItems { column-gap: 2px !important; }
  #send_form #leftSendForm, #send_form #rightSendForm {
    flex-direction: row !important; flex-wrap: nowrap !important; width: auto !important;
    flex: 0 0 auto; align-items: center; gap: 0; padding: 0;
  }
  #send_form #leftSendForm { order: 1; }
  #send_form #rightSendForm { order: 3; }
  #send_form #send_textarea {
    order: 2; flex: 1 1 0 !important; width: 0 !important; min-width: 0 !important;
    min-height: 40px !important; padding: 9px 4px !important; margin: 0 !important;
    font-size: max(16px,var(--mainFontSize)) !important; line-height: 22px !important;
    box-sizing: border-box;
  }
  #send_form #leftSendForm > div, #send_form #rightSendForm > div {
    width: 34px !important; min-width: 34px !important; height: 40px !important;
    min-height: 40px !important; flex-shrink: 0; font-size: 22px; margin: 0 !important;
  }
  #send_form #input_helper_toolbar :is(button,.input-helper-btn) {
    min-width: 32px; height: 34px; padding-inline: 6px;
  }
  #top-settings-holder .drawer-toggle {
    min-height: 40px; display: flex; align-items: center; justify-content: center;
  }
}
@media (pointer: coarse) {
  #chat .mes_button { min-width: 32px; min-height: 32px; align-content: center; text-align: center; }
}
@media (hover: hover) {
  .drawer-content :is(.inline-drawer-header,.standoutHeader):hover { background: #ffffff05 !important; }
  #top-settings-holder .drawer-toggle:hover .drawer-icon { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  #send_form, .drawer-content :is(.inline-drawer-header,.standoutHeader) { transition: none; }
}
/* 浏览器不支持毛玻璃时，用较实的底色保证文字可读。 */
@supports not (backdrop-filter: blur(1px)) {
  @supports not (-webkit-backdrop-filter: blur(1px)) {
    #send_form, body.no-blur #send_form { background: rgba(40,40,40,.95) !important; }
    .drawer-content, body.no-blur .drawer-content { background:rgb(32,32,32) !important; }
  }
}


