  background: radial-gradient(ellipse at 50% 72%,rgba(238,238,238,.11) 0%,rgba(238,238,238,.045) 45%,transparent 78%);
  border-radius: .35em;
  -webkit-box-decoration-break: clone; box-decoration-break: clone;
  text-shadow: 0 0 2px rgba(255,255,255,.25), 0 0 7px rgba(235,235,235,.15);
}

#chat > .mes[is_user="true"] .mes_text q {
  color: var(--SmartThemeQuoteColor, #f2f2f2); padding: 0; background: none;
  border-radius: 0; text-shadow: none;
}


/* 右上方等位置弹出的通知：底色、文字、关闭按钮。 */
body #toast-container > .toast {
  box-sizing: border-box;
  width: 360px !important;
  max-width: calc(100vw - 24px); min-height: 56px;
  padding: 13px 38px 13px 46px; margin-bottom: 10px;
  position: relative; overflow: hidden;
  border: 1px solid #ffffff1c;
  border-radius: 14px;
  background-color: rgba(35,35,35,.97) !important;

  background-size: 18px 18px !important;
  background-position: 16px 17px !important;
  background-repeat: no-repeat !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  box-shadow: 0 8px 24px #0000003d, inset 0 1px 0 #ffffff0d !important;
  color: #ddd; font-family: var(--mainFontFamily);
  font-size: calc(var(--mainFontSize,15px) * .95); line-height: 1.55;
  text-shadow: none;
}
body #toast-container > .toast .toast-title {
  color: #ededed; font-size: 1em; font-weight: 600;
  line-height: 1.5; margin: 0 0 3px; overflow-wrap: anywhere;
}
body #toast-container > .toast .toast-message {
  color: #bdbdbd; font-size: .92em; line-height: 1.6;
  overflow-wrap: anywhere; word-break: normal;
}
body #toast-container > .toast .toast-message a {
  color: #e1e1e1; text-decoration: underline; text-underline-offset: 3px;
}
body #toast-container > .toast .toast-close-button {
  position: absolute; top: 7px; right: 7px;
  width: 26px; height: 26px; min-width: 0; margin: 0; padding: 0;
  border: 0; border-radius: 7px; background: transparent;
  color: #c3c3c3; font-family: Arial,sans-serif;
  font-size: 19px; font-weight: 400; line-height: 26px;
  opacity: .7; text-shadow: none; box-shadow: none;
}
body #toast-container > .toast .toast-close-button:hover,
body #toast-container > .toast .toast-close-button:focus-visible {
  opacity: 1; color: #fff; background: #ffffff0c;
}
body #toast-container > .toast .toast-close-button:focus-visible {
  outline: 1px solid #ffffff80; outline-offset: -2px;
}
body #toast-container > .toast .toast-progress {
  height: 2px; background-color: #bdbdbd; opacity: .45;
}
body.no-blur #toast-container > .toast {
  background-color: #242424 !important;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
@supports not (backdrop-filter: blur(1px)) {
  @supports not (-webkit-backdrop-filter: blur(1px)) {
    body #toast-container > .toast { background-color: #242424 !important; }
  }
}


/* 输入栏底部亮线；聚焦输入框时会呼吸发光。减少动态效果时关闭动画。 */
#send_form { position: relative; }
#send_form, body.no-blur #send_form, #send_form:focus-within {
  border: 0 !important;
  box-shadow: none !important;
  outline: none !important;
}
#send_form::after {
  content: ""; position: absolute; inset: 0;
  border-radius: inherit; box-sizing: border-box;
  border: 0;
  background: transparent; pointer-events: none;
  box-shadow: 0 0 10px rgba(242,242,242,.10), 0 0 20px rgba(242,242,242,.05);
  opacity: 0;
  transition: opacity .28s ease, box-shadow .28s ease;
}
#send_form:has(#send_textarea:focus)::after {
  box-shadow: 0 0 12px rgba(245,245,245,.16), 0 0 26px rgba(242,242,242,.09);
  animation: silver-mist-input-light 4.8s ease-in-out infinite;
}
@keyframes silver-mist-input-light {
  0%, 100% { opacity: .66; }
  50% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  #send_form::after { transition: none; }
  #send_form:has(#send_textarea:focus)::after { animation: none; opacity: .9; }
}


/* 设置面板展开位置：贴在顶栏下方，手机上铺到两侧。 */
