  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22184%22%20height%3D%2232%22%20viewBox%3D%220%200%20184%2032%22%3E%3Ctext%20x%3D%2292%22%20y%3D%2216%22%20dy%3D%22.35em%22%20text-anchor%3D%22middle%22%20fill%3D%22%23bcbcbc%22%20fill-opacity%3D%22.75%22%20font-family%3D%22Arial%2C%20%27PingFang%20SC%27%2C%20%27Segoe%20UI%20Symbol%27%2C%20sans-serif%22%20font-size%3D%2216%22%3E%E2%82%8D%5E%CB%B6-%F0%96%A5%A6-%CB%B5%5E%E2%82%8E%E0%A9%AD%3C%2Ftext%3E%3C%2Fsvg%3E") !important;
