body:not(.sl-header-managed):not(:has(#chat .welcomePanel)) #chat > .mes:nth-child(1 of .mes[is_user="false"]:not(.smallSysMes)) .name_text {display:none !important;}
body:not(.sl-header-managed):not(:has(#chat .welcomePanel)):has(#chat > .mes[is_user="false"]:not(.smallSysMes)) #sheld::after {content:"";position:fixed;top:0;right:calc(50% - var(--sl-header-width) / 2 + 20px);width:100px;height:84px;background:var(--sl-header-art) center top / var(--sl-header-art-size,contain) no-repeat;pointer-events:none;z-index:31;filter:brightness(1.14) drop-shadow(0 0 1px #ffffffb3) drop-shadow(0 0 3px #ffffff70) drop-shadow(0 0 6px #ffffff30);}
