/* 配套插件显示的消息信息：楼层、时间等小字。opacity:.52 控制浓淡。 */
#chat > .mes:not(.smallSysMes) .sl-message-meta {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end;
  gap: 2px 9px; width: fit-content; max-width: 100%; margin: -7px 0 10px auto;
  color: var(--scene-muted); font-size: .64em; line-height: 1.25; opacity: .52;
  letter-spacing: .015em; pointer-events: none;
}
#chat > .mes:not(.smallSysMes) .sl-message-meta[hidden] { display: none !important; }
#chat > .mes:not(.smallSysMes) .sl-message-meta span { white-space: nowrap; }
body.sl-message-meta-active #chat > .mes:not(.smallSysMes) :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay,.timestamp) { display: none !important; }
#chat > .mes[is_user="true"]:not(.smallSysMes) { grid-template-columns: minmax(0,680px) 48px !important; }
