#chat > .mes[is_user="true"]:not(.smallSysMes) > .mesAvatarWrapper .avatar { margin-inline: auto; }
#chat > .mes[is_user="true"]:not(.smallSysMes) .name_text { width: 48px; }
#chat > .mes[is_user="true"]:not(.smallSysMes) > .mes_block > .sl-message-meta { grid-column: 1; grid-row: 2; justify-self: end; margin: -4px 0 3px; }
#chat .mes_reasoning_header { width: 120px !important; height: 36px !important; }
#chat .mes_reasoning_header::before { width: 104px !important; height: 30px !important; }

/* 角色名字左右位置：4px 往右移，负数往左移。 */
#chat > .mes[is_user="false"]:not(.smallSysMes) .name_text {
  transform: translateX(4px) !important;
}


/* 电脑双层背景：在插件中开启，窗口宽于 1000px 时生效。 */
@media (min-width: 1001px) {
  body.softlight-background-active.sl-desktop-layers #bg1 {
