/* 日间配色开始。 */
:root{--sl-paired-theme:1;--sl-night-body:rgba(227, 227, 227, 1);--sl-night-em:rgba(190, 190, 190, 1);--sl-night-underline:rgba(209, 209, 209, 1);--sl-night-quote:rgba(251, 251, 251, 1);--sl-night-tint:rgba(26, 26, 26, 0.61);--sl-night-chat:rgba(0, 0, 0, 0);--sl-night-user:rgba(0, 0, 0, 0);--sl-night-bot:rgba(0, 0, 0, 0);--sl-night-border:rgba(165, 165, 165, 0.25);--sl-night-shadow:rgba(0, 0, 0, 0);}
/* 日间界面：浅色底、深色字。 */
html.sl-studio-daylight{color-scheme:light;--SmartThemeBodyColor:rgba(28,28,28,1) !important;--SmartThemeEmColor:rgba(65,65,65,1) !important;--SmartThemeUnderlineColor:rgba(46,46,46,1) !important;--SmartThemeQuoteColor:rgba(4,4,4,1) !important;--SmartThemeBlurTintColor:rgba(229,229,229,0.61) !important;--SmartThemeChatTintColor:rgba(255,255,255,0) !important;--SmartThemeUserMesBlurTintColor:rgba(255,255,255,0) !important;--SmartThemeBotMesBlurTintColor:rgba(255,255,255,0) !important;--SmartThemeBorderColor:rgba(90,90,90,0.25) !important;--SmartThemeShadowColor:rgba(255,255,255,0) !important;}
/* 日间设置面板：底色、模糊和圆角。 */
html.sl-studio-daylight{--scene-image: none;--scene-dim: .60;--scene-blur: 0px;--scene-x: 50%;--scene-y: 25%;--scene-font: 17px;--scene-ink: var(--SmartThemeBodyColor, rgba(28,28,28,1));--scene-muted: rgba(88,88,88,1);--scene-mist: rgba(0,0,0,0.055);--scene-edge: rgba(0,0,0,0.09);--scene-drawer-tint:rgb(224,224,224);--scene-drawer-blur:0px;--scene-radius: 26px;}
html.sl-studio-daylight body{text-shadow:none;}
html.sl-studio-daylight #bg1,html.sl-studio-daylight #bg_custom{background-position:var(--scene-x) var(--scene-y) !important;}
html.sl-studio-daylight body::before{background:var(--scene-image) var(--scene-x) var(--scene-y)/cover no-repeat;}
html.sl-studio-daylight body::after{background:rgba(0,0,0,var(--scene-dim));}
html.sl-studio-daylight #sheld{background:transparent !important;border:0;box-shadow:none;}
html.sl-studio-daylight #chat{background:transparent !important;border:0 !important;box-shadow:none;text-shadow:none;scrollbar-color:rgba(0,0,0,0.149) transparent;}
html.sl-studio-daylight #chat>.mes:not(.smallSysMes){color:var(--scene-ink);background:transparent !important;border:0 !important;border-radius:0;box-shadow:none !important;}
html.sl-studio-daylight #chat>.mes:not(.smallSysMes) .name_text{color:var(--scene-muted);}
html.sl-studio-daylight #chat>.mes[is_user="false"]:not(.smallSysMes) .name_text::before{border-radius:50%;background:#ddd;box-shadow:0 0 7px 2px #ffffff2b;}
html.sl-studio-daylight #chat>.mes:not(.smallSysMes) .timestamp{color:var(--scene-muted);}
