/* 配套顶栏：头像、文案和挂饰的固定布局。 */
:root {--sl-header-width:min(var(--sheldWidth,100vw),100vw);}
@media(max-width:1000px) {:root {--sl-header-width:100vw;}}
.sl-chat-header {
  box-sizing:border-box; position:fixed; top:0; left:50%; transform:translateX(-50%);
  width:var(--sl-header-width); height:84px; z-index:31;
  display:flex; align-items:center; gap:16px; padding:10px 20px;
  pointer-events:none; color:#dedede; font-family:var(--mainFontFamily,serif);
  background:linear-gradient(#11111150,transparent); border:0; box-shadow:none;
}
.sl-chat-header[hidden] {display:none !important;}
.sl-header-avatar {position:relative;flex:0 0 48px;width:48px;height:48px;}
.sl-header-avatar img {width:84%;height:84%;margin:8%;border-radius:50%;object-fit:cover;display:block;opacity:.85;}
.sl-header-avatar::before {content:"";position:absolute;width:184%;height:184%;left:-48%;top:-40%;background:var(--sl-header-frame) center / contain no-repeat;pointer-events:none;filter:blur(.2px) brightness(1.14) drop-shadow(0 0 1px #ffffffb3) drop-shadow(0 0 3px #ffffff70) drop-shadow(0 0 6px #ffffff30);}
.sl-header-avatar::after {content:none;}
.sl-header-copy {min-width:0;flex:1;padding-right:2px;}
.sl-header-name {display:block;font-size:16px;font-weight:400;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sl-header-caption {display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere;font-size:10px;font-weight:400;line-height:1.5;letter-spacing:.04em;color:#b5b5b5;}
.sl-header-art {flex:0 0 100px;align-self:flex-start;width:100px;height:84px;margin-top:-10px;background:var(--sl-header-art) center top / var(--sl-header-art-size,contain) no-repeat;filter:brightness(1.14) drop-shadow(0 0 1px #ffffffb3) drop-shadow(0 0 3px #ffffff70) drop-shadow(0 0 6px #ffffff30);}
@media(max-width:360px) {
  .sl-chat-header {gap:12px;padding-left:17px;padding-right:8px;}
  .sl-header-avatar {flex-basis:40px;width:40px;height:40px;}
  .sl-header-art {flex-basis:74px;width:74px;}
  .sl-header-name {font-size:15px;}
  .sl-header-caption {font-size:10px;letter-spacing:0;}
}

/* 聊天背景层与页面滚动条：隐藏滑杆，仍可滚动。 */
#softlight-scene-v1 {position:fixed;left:0;top:0;width:100vw;height:100vh;height:100dvh;z-index:3;pointer-events:none;overflow:hidden;background:#171717;isolation:isolate;}
#softlight-scene-v1[hidden] {display:none !important;}
#softlight-scene-v1 .sl-scene {position:absolute;inset:0;overflow:hidden;}
#softlight-scene-v1 .sl-mist {position:absolute;inset:-48px;background-position:center;background-size:cover;filter:blur(32px) brightness(.6);}
#softlight-scene-v1 .sl-picture {position:absolute;inset:0;width:100%;height:100%;object-fit:contain;}
#softlight-scene-v1 .sl-shade {position:absolute;inset:0;background:#000;pointer-events:none;}
body.softlight-background-active::before,body.softlight-background-active::after {opacity:0 !important;}
body.softlight-background-active #bg1,body.softlight-background-active #bg_custom {visibility:hidden !important;}
#chat, html, body, body * {scrollbar-width:none !important;}
html::-webkit-scrollbar, body::-webkit-scrollbar, body *::-webkit-scrollbar {display:none !important;width:0 !important;height:0 !important;}
#softlight-header-v1 .sl-header-avatar {pointer-events:auto;cursor:pointer;}
#softlight-header-v1 .sl-header-avatar:focus-visible {outline:1px solid #ddd;outline-offset:4px;border-radius:50%;}

/* 顶栏尺寸与取景：数值由配套设置传入。 */
.sl-chat-header {height:var(--sl-custom-header-height,84px);background-size:100% 84px;background-repeat:no-repeat;}
.sl-header-avatar {flex-basis:var(--sl-avatar-size,48px);width:var(--sl-avatar-size,48px);height:var(--sl-avatar-size,48px);transform:translateY(var(--sl-avatar-y,0px));}
.sl-header-art {flex-basis:var(--sl-art-size,100px);width:var(--sl-art-size,100px);height:var(--sl-custom-header-height,84px);transform:translate(var(--sl-art-x,0px),var(--sl-art-y,0px));}
.sl-header-copy {transform:translateY(var(--sl-avatar-y,0px));}
.sl-header-avatar[data-frame-mode="hidden"]::before {display:none;}
.sl-header-avatar[data-frame-mode="custom"]::before {display:block;width:var(--sl-frame-size,100%);height:var(--sl-frame-size,100%);left:calc(50% + var(--sl-frame-x,0%));top:calc(50% + var(--sl-frame-y,0%));transform:translate(-50%,-50%);background:var(--sl-frame-image) center/contain no-repeat;filter:none;z-index:1;}
.sl-header-avatar .sl-avatar-crop {display:block;width:84%;height:84%;margin:8%;border-radius:50%;overflow:hidden;}
.sl-header-avatar .sl-avatar-crop img {display:block;width:100%;height:100%;margin:0;border-radius:0;object-fit:cover;object-position:var(--sl-avatar-crop-x,50%) var(--sl-avatar-crop-y,50%);transform:scale(var(--sl-avatar-crop-zoom,1));transform-origin:var(--sl-avatar-crop-x,50%) var(--sl-avatar-crop-y,50%);}
.sl-header-art[data-custom="true"] {filter:none !important;}
.sl-header-art[data-pendant-hidden="true"] {visibility:hidden !important;}
.sl-header-caption[hidden] {display:none !important;}
html body.sl-header-visible #sheld#sheld {top:calc(var(--sl-tauri-top,0px) + var(--sl-custom-header-height,84px)) !important;height:calc(var(--tt-base-viewport-height,100dvh) - var(--sl-tauri-top,0px) - var(--sl-custom-header-height,84px)) !important;max-height:calc(var(--tt-base-viewport-height,100dvh) - var(--sl-tauri-top,0px) - var(--sl-custom-header-height,84px)) !important;}
@media(max-width:360px) {
  .sl-header-avatar {flex-basis:var(--sl-avatar-size,40px);width:var(--sl-avatar-size,40px);height:var(--sl-avatar-size,40px);}
  .sl-header-art {flex-basis:var(--sl-art-size,74px);width:var(--sl-art-size,74px);}
}

/* 启动配色：由配套插件记住日间、夜间或跟随系统。 */
