:is(.mes_text, .mes_reasoning, .mes_text > content, .mes_reasoning > content)
> :is(p:not([class]):not([style]):not([id]), .sl-indent-line) {
  text-shadow: 1px 1px 0 rgba(0, 0, 0, .5) !important;
}

/* 引用、斜体和加粗沿用同一层阴影 */
html body #chat > .mes:not(.smallSysMes)
:is(.mes_text, .mes_reasoning, .mes_text > content, .mes_reasoning > content)
> :is(p:not([class]):not([style]):not([id]), .sl-indent-line)
:is(q, em, i, strong, b, u, a):not([class]):not([style]):not([id]) {
