html body #send_form #send_textarea::placeholder {
  font-size: 14px !important;
}

/* 仅 AI 楼层：消息操作按钮移到正文下方 */
html body #chat#chat > .mes[is_user="false"]:not(.smallSysMes):not([type="welcome_prompt"]) {
  position: relative !important;
  flex-shrink: 0 !important;

  /* 正文下方预留空间：调大，底部空隙增大 */
  padding-bottom: 80px !important;
}

